275	 * it equals a protected file present in the workspace, tracked, untracked or ignored, or shares a significant line
276	 * with one (see `protectedContent`); that covers `cp .env notes.txt` and a partial copy of any size.
277	 * Limits of that comparison, where credential redaction is the only guard: lines pasted from a protected file into a
278	 * file that already existed at the base (modified files are not line-compared); any re-formatting of a protected
279	 * file's lines (quoting, a changed separator, values only, re-encoding), because a line matches only exactly once
280	 * trimmed and is at least 8 characters; and a protected file whose lines are all shorter than that, which is caught
281	 * only by an exact whole-file match. The trade-off is over-omission: a new file sharing a common line (such as
282	 * NODE_ENV=development) with any protected file in the workspace, an ignored `.env*` included, is omitted and noted.
283	 * The pass listing ignored files takes up to IGNORED_LISTING_TIMEOUT_MS (about 6 s per 90k ignored files); a tree too
284	 * large for it fails closed with an error rather than being trusted.
285	 * Any git failure or an unmanageable path count returns an error: nothing is ever kept because it could not be
286	 * classified.
287	 */
288	export interface CandidateDiff { base: string; diff: string; omitted: number; omittedNew: number; omittedNested: number }
289	/** A refusal because the repository state is outside the supported domain (as opposed to a git failure). */
290	export type CandidateDiffError = { error: string; unsupported?: string };
291	export function candidateDiff(workspace: string, base: string | undefined, policyWorkspace?: string): CandidateDiff | CandidateDiffError {
292	  const root = path.resolve(workspace);
293	  let scratch: string | undefined;
294	  let attrs: { tree: string; objects: string } | undefined;
295	  let pin: string[] = [];
296	  // `ownIndex` reads the repository's own index (never written: only listed); everything else uses the scratch index.
297	  const git = (args: string[], options: { okExit?: number[]; input?: string; maxBuffer?: number; ownIndex?: boolean; timeoutMs?: number } = {}): string => {
298	    try {
299	      return execFileSync("git", [...pin, ...GIT_SAFE, ...args], {
300	        cwd: root, env: safeGitEnv(options.ownIndex ? undefined : path.join(scratch!, "index"), attrs), encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"],
301	        timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER, ...(options.input === undefined ? {} : { input: options.input }),
302	      });
303	    } catch (err: any) {
304	      if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
305	      throw err;
306	    }
307	  };
308	  try {
309	    // Host-side git runs only where the checkout is trusted (the agent may have replaced `.git` or planted a repository),
310	    // and then against the verified git dir and work tree.
311	    pin = trustedGitArgs(root);
312	    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-candidate-index-"));
313	    // The policy is the operator's (their workspace), not whatever a unit's own worktree holds: an untracked
314	    // .nexus-security.json never reaches a worktree.
315	    const security = new SecurityManager(policyWorkspace ?? root);
316	    // A base read from persisted JSON is resolved as a commit before use: a value shaped like an option is refused.
317	    const support = snapshotSupport((args) => git(args, { ownIndex: true, maxBuffer: LISTING_MAX_BUFFER }), root);
318	    if ("unsupported" in support) return { error: `automatic inputs are not available for this repository state: ${support.unsupported}; give the unit explicit inputs instead`, unsupported: support.unsupported };
319	    const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
320	    git(["read-tree", "--end-of-options", commit]);
321	    const listing = (args: string[], ownIndex = false, timeoutMs?: number) => git(["ls-files", "-z", ...args], { maxBuffer: LISTING_MAX_BUFFER, ownIndex, timeoutMs }).split("\0").filter(Boolean);
322	    // New paths: untracked files git does not ignore, plus files tracked now but not at the base (a force-added file
323	    // can match .gitignore and still be part of the candidate).
324	    const atBase = new Set(listing([]));
325	    // A path tracked since the base but already removed from disk is a deletion against nothing: it has no content to
326	    // show, and git would reject it as a pathspec.
327	    const onDisk = (p: string) => { try { fs.lstatSync(path.join(root, p)); return true; } catch { return false; } };
328	    const ownIndex = new Set(listing([], true));
329	    // Untracked, non-ignored entries, listed once. A directory entry (trailing slash) is an untracked nested git
330	    // repository, which `git add` refuses: it is skipped and counted rather than failing every review.
331	    const others = listing(["--others", "--exclude-standard"]);
332	    const omittedNested = others.filter((p) => p.endsWith("/")).length;
333	    const untracked = others.filter((p) => !p.endsWith("/"));
334	    attrs = attributesTree(root, scratch, [...new Set([...untracked, ...ownIndex])], pin);
335	    // A path tracked at the base but removed from the real index (`git rm --cached`) is part of the candidate as a
336	    // deletion even when the file stays on disk: force it out of the scratch index too (its entry can match neither HEAD nor the worktree), and never re-add it as new.
337	    const removed = [...atBase].filter((p) => !ownIndex.has(p));
338	    if (removed.length) {
339	      git(["--literal-pathspecs", "rm", "--cached", "--force", "--quiet", "--ignore-unmatch", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${removed.join("\0")}\0` });
340	    }
341	    const removedSet = new Set(removed);
342	    const added = new Set([
343	      ...untracked.filter((p) => !removedSet.has(p)),
344	      ...[...ownIndex].filter((p) => !atBase.has(p) && onDisk(p)),
345	    ]);
346	    if (added.size) {
347	      git(["--literal-pathspecs", "add", "--force", "--intent-to-add", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${[...added].join("\0")}\0` });
348	    }
349	    // Comparing worktree content runs a path's clean filter, so before any diff every path is checked for a filter or
350	    // diff driver the stripped attribute source did not neutralise ($GIT_DIR/info/attributes, or a worktree
351	    // .gitattributes on Git before 2.40); one that applies is refused, never run. The check is batched so the
352	    // repository's size never turns into a failure.
353	    const refusal = driverRefusal((args, input) => git(args, { input }), listing([]));
354	    if (refusal) return { error: refusal };
355	    // name-status with rename detection (no limit on the exhaustive pass), only to learn which paths belong together.
356	    const tokens = git(["diff", "--name-status", "-z", "-M", "-C", "--find-copies-harder", "-l0", "--relative", "--no-ext-diff", "--no-textconv", "--end-of-options", commit, "--"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0");
357	    const groups: Array<{ status: string; paths: string[] }> = [];
358	    for (let i = 0; i < tokens.length; ) {
359	      const status = tokens[i++];
360	      if (!status) continue;
361	      const count = status[0] === "R" || status[0] === "C" ? 2 : 1;
362	      const paths = tokens.slice(i, i + count);
363	      i += count;
364	      if (paths.length !== count || paths.some((p) => !p)) return { error: "git reported a changed path that could not be read" };
365	      groups.push({ status, paths });
366	    }
367	    if (groups.length > MAX_DIFF_PATHS) return { error: `the change touches more than ${MAX_DIFF_PATHS} paths; scope it with explicit inputs` };
368	    const isProtected = (group: { paths: string[] }) => group.paths.some((p) => inputPathProtection(security, p) !== undefined);
369	    const protectedChanged = groups.some(isProtected);
370	    // Git's copy detection stops at its similarity threshold and never sees an ignored protected file, so an added file
371	    // is also compared with the content of every protected file present in the workspace.
372	    const sources = protectedMatcher((args, timeoutMs) => git(args, { maxBuffer: LISTING_MAX_BUFFER, timeoutMs }), root, policyWorkspace, security, [...atBase, ...ownIndex, ...untracked]);
373	    let omitted = 0;
374	    let omittedNew = 0;
375	    const allowed: string[] = [];
376	    for (const group of groups) {
377	      if (isProtected(group)) omitted++;
378	      // A copy or rename is a new file too: its destination is compared with the protected content like an added file.
379	      else if ("ACR".includes(group.status[0]) && ((group.status[0] === "A" && protectedChanged) || sources.carriedBy(root, group.paths[group.paths.length - 1]))) omittedNew++;
380	      else allowed.push(...group.paths);
381	    }
382	    const diff = allowed.length ? git(["diff", ...DIFF_FLAGS, "--end-of-options", commit, "--", ...allowed.map((p) => `:(literal)${p}`)]) : "";
383	    return { base: commit, diff, omitted, omittedNew, omittedNested };
384	  } catch (err: any) {
385	    if (err instanceof UntrustedCheckoutError) return { error: `automatic inputs are not available: ${err.message}` };
386	    if (err?.code === "ENOBUFS" || /ENOBUFS/.test(String(err?.message))) {
387	      return { error: `the candidate diff is too large to show (over ${GIT_MAX_BUFFER / (1024 * 1024)} MiB); scope it with explicit inputs` };
388	    }
389	    return { error: `git could not produce the diff (${String(err?.message ?? err).split("\n")[0].slice(0, 120)})` };
390	  } finally {
391	    if (scratch) fs.rmSync(scratch, { recursive: true, force: true });
392	  }
393	}
394	
395	/**
396	 * The comparison of new files with the protected files present in the workspace: tracked, untracked and ignored (listed
397	 * through `git`, a pinned call in the workspace), plus the operator's own when the unit runs in another worktree. A
398	 * failure (timeout, buffer) propagates: the comparison is never silently skipped.
399	 */
400	function protectedMatcher(git: (args: string[], timeoutMs?: number) => string, root: string, policyWorkspace: string | undefined, security: SecurityManager, known: Iterable<string>): ReturnType<typeof protectedContent> {
401	  const ignored = git(["ls-files", "-z", "--others", "--ignored", "--exclude-standard"], IGNORED_LISTING_TIMEOUT_MS).split("\0").filter((p) => p && !p.endsWith("/"));
402	  const protectedSources = [...new Set([...known, ...ignored])]
403	    .filter((p) => inputPathProtection(security, p) !== undefined).map((file) => ({ root, file }));
404	  // A unit's worktree lacks the operator's untracked and ignored secrets (.env), so those are compared too.
405	  if (path.resolve(policyWorkspace ?? root) !== root) {
406	    const operator = path.resolve(policyWorkspace!);
407	    // The operator's own checkout is not agent-writable: it is pinned like any checkout, but a repository nested in it (an untracked clone) is normal there.
408	    const operatorCheckout = verifyCheckout(operator);
409	    if (operatorCheckout.reason) throw new UntrustedCheckoutError(operator, operatorCheckout.reason, []);
410	    const operatorPin = operatorCheckout.gitDir ? ["--git-dir", operatorCheckout.gitDir, "--work-tree", operatorCheckout.workTree!] : [];
411	    for (const extra of [[], ["--ignored"]]) {
412	      const listed = execFileSync("git", [...operatorPin, ...GIT_SAFE, "ls-files", "-z", "--cached", "--others", ...extra, "--exclude-standard"], {
413	        cwd: operator, env: safeGitEnv(undefined), encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: IGNORED_LISTING_TIMEOUT_MS, maxBuffer: LISTING_MAX_BUFFER,
414	      }).split("\0").filter((p) => p && !p.endsWith("/") && inputPathProtection(security, p) !== undefined);
415	      for (const file of listed) protectedSources.push({ root: operator, file });
416	    }
417	  }
418	  return protectedContent(protectedSources);
419	}
420	
421	/**
422	 * A plain candidate diff for review units when the repository state is outside the supported domain: tracked changes
423	 * against the base (`git diff`, no copy detection, no scratch index) plus untracked files. The same
424	 * guards apply that do not depend on the domain: the checkout is verified and pinned, no driver runs, protected paths
425	 * are left out, and a new file carrying protected content is omitted. It can be wrong where the predicate refuses (a
426	 * sparse checkout shows its absent files as deleted, an LFS pointer differs from its content), which is why the reviewer
427	 * is told it is a plain diff.
428	 */
429	export function plainCandidateDiff(workspace: string, base: string | undefined, policyWorkspace?: string): CandidateDiff | { error: string } {
430	  const root = path.resolve(workspace);
431	  let scratch: string | undefined;
432	  try {
433	    const pin = trustedGitArgs(root);
434	    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-plain-index-"));
435	    const env = safeGitEnv(path.join(scratch, "index"));
436	    const git = (args: string[], options: { okExit?: number[]; timeoutMs?: number; maxBuffer?: number } = {}): string => {
437	      try {
438	        return execFileSync("git", [...pin, ...GIT_SAFE, ...args], { cwd: root, env, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER });
439	      } catch (err: any) {
440	        if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
441	        throw err;
442	      }
443	    };
444	    const security = new SecurityManager(policyWorkspace ?? root);
445	    const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
446	    // The base tree in a private index: no flag of the real index (skip-worktree, assume-unchanged) can hide a file.
447	    git(["read-tree", "--end-of-options", commit]);
448	    // No content is compared (no clean filter can run) before every path is known to have no driver.
449	    const driverCheck = (files: string[]) => driverRefusal((args, input) => execFileSync("git", [...pin, ...GIT_SAFE, ...args], { cwd: root, env, encoding: "utf8", input, stdio: ["pipe", "pipe", "pipe"], timeout: 30_000, maxBuffer: GIT_MAX_BUFFER }), files);
450	    const listed = [...git(["ls-files", "-z", "--cached"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0"), ...git(["ls-files", "-z", "--others", "--exclude-standard"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0")].filter((p) => p && !p.endsWith("/"));
451	    const early = driverCheck(listed);
452	    if (early) return { error: early };
453	    const tracked = git(["diff", "--name-only", "-z", "--ignore-submodules=all", "--relative", "--no-renames", "--no-ext-diff", "--no-textconv", "--"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0").filter(Boolean);
454	    const others = git(["ls-files", "-z", "--others", "--exclude-standard"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0").filter(Boolean);
455	    const omittedNested = others.filter((p) => p.endsWith("/")).length;
456	    const untracked = others.filter((p) => !p.endsWith("/"));
457	    if (tracked.length + untracked.length > MAX_DIFF_PATHS) return { error: `the change touches more than ${MAX_DIFF_PATHS} paths; scope it with explicit inputs` };
458	    const allowedTracked = tracked.filter((p) => inputPathProtection(security, p) === undefined);
459	    const sources = protectedMatcher((args, timeoutMs) => git(args, { maxBuffer: LISTING_MAX_BUFFER, timeoutMs }), root, policyWorkspace, security, [...tracked, ...untracked]);
460	    let omitted = tracked.length - allowedTracked.length;
461	    let omittedNew = 0;
462	    const allowedNew: string[] = [];
463	    // As in the main builder: once any protected path changed (a protected file moved leaves no source on disk), no new file is shown.
464	    const protectedChanged = allowedTracked.length !== tracked.length;
465	    for (const file of untracked) {
466	      if (inputPathProtection(security, file) !== undefined) omitted++;
467	      else if (protectedChanged || sources.carriedBy(root, file)) omittedNew++;
468	      else allowedNew.push(file);
469	    }
470	    let diff = allowedTracked.length ? git(["diff", "--no-color", "--no-ext-diff", "--no-textconv", "--no-renames", "--ignore-submodules=all", "--relative", "--", ...allowedTracked.map((p) => `:(literal)${p}`)]) : "";
471	    for (const file of allowedNew) diff += git(["diff", "--no-color", "--no-ext-diff", "--no-textconv", "--no-index", "--", "/dev/null", file], { okExit: [1] });
472	    return { base: commit, diff, omitted, omittedNew, omittedNested };
473	  } catch (err: any) {
474	    if (err instanceof UntrustedCheckoutError) return { error: `automatic inputs are not available: ${err.message}` };
475	    if (err?.code === "ENOBUFS" || /ENOBUFS/.test(String(err?.message))) return { error: `the candidate diff is too large to show (over ${GIT_MAX_BUFFER / (1024 * 1024)} MiB)` };
476	    return { error: `git could not produce the diff (${String(err?.message ?? err).split("\n")[0].slice(0, 120)})` };
477	  } finally {
478	    if (scratch) fs.rmSync(scratch, { recursive: true, force: true });
479	  }
480	}
481	
482	/** Credential-redacted and bounded to the input limit, with a marker when cut. */
483	export function boundedRedactedInput(text: string): string {
484	  const redacted = redactForPersistence(text);
485	  return redacted.length > MAX_SPECIALIST_INPUT_CHARS ? `${redacted.slice(0, MAX_SPECIALIST_INPUT_CHARS - 16)}\n[truncated]` : redacted;
486	}
