1	/**
2	 * Shared rules for text that becomes a unit's input: which workspace paths may never be read into it, how the
3	 * candidate diff is built without them, and the credential redaction applied before it is persisted or prompted.
4	 */
5	import * as fs from "node:fs";
6	import * as os from "node:os";
7	import * as path from "node:path";
8	import { execFileSync } from "node:child_process";
9	import { createHash } from "node:crypto";
10	import { SecurityManager } from "../security.js";
11	import { MAX_SPECIALIST_INPUT_CHARS } from "./specialist_profiles.js";
12	import { redactForPersistence } from "./persistence_protection.js";
13	import { trustedGitArgs } from "../git.js";
14	import { verifyCheckout } from "./checkout_trust.js";
15	import { UntrustedCheckoutError } from "../worktrunk/git.js";
16	
17	/**
18	 * Whether a workspace-relative path is off limits as input text: protected by the workspace security policy (the one
19	 * read_file applies), or inside Nexus's own state directory (`.nexus`, compared case-insensitively because the
20	 * filesystem may be).
21	 */
22	export function inputPathProtection(security: SecurityManager, relative: string): string | undefined {
23	  const segments = relative.split(/[\\/]/).map((segment) => segment.toLowerCase());
24	  if (segments.includes(".nexus")) return "inside .nexus";
25	  const check = security.isPathProtected(relative);
26	  return check.protected ? (check.reason ?? "protected by the security policy") : undefined;
27	}
28	
29	/**
30	 * Global options for every git call that reads the workspace for a prompt. Rendering is pinned, and nothing the
31	 * repository configures may run in this process: no fsmonitor hook, no hooks, no replace objects, no system or
32	 * per-user attributes, no automatic gc. Clean/smudge filters are kept out by the attribute source below.
33	 */
34	export const GIT_SAFE = [
35	  "--no-replace-objects",
36	  "-c", "core.quotepath=false", "-c", "diff.noprefix=false", "-c", "diff.mnemonicPrefix=false", "-c", "diff.external=", "-c", "core.pager=cat",
37	  "-c", "core.fsmonitor=false", "-c", "core.hooksPath=/dev/null", "-c", "core.attributesFile=/dev/null", "-c", "core.untrackedCache=false",
38	  "-c", "gc.auto=0", "-c", "maintenance.auto=false",
39	];
40	/** Git's empty tree: as GIT_ATTR_SOURCE (Git 2.40+) it means the worktree's .gitattributes assign no attribute. */
41	const EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904";
42	
43	/**
44	 * The environment for those calls: inherited GIT_* variables (GIT_DIR, GIT_INDEX_FILE, GIT_CONFIG_PARAMETERS, ...)
45	 * are dropped, system config and system attributes are ignored, replace objects are off, and attributes come from
46	 * a tree of the worktree's own .gitattributes files with every filter and diff assignment removed (the empty tree when
47	 * there are none), so `text`/`eol` normalization still applies but no driver does. `$GIT_DIR/info/attributes` still
48	 * applies (and on Git older than 2.40 so do the worktree's .gitattributes), so a filter or diff driver assigned that
49	 * way is refused before any command could invoke it.
50	 */
51	export function safeGitEnv(indexFile: string | undefined, attrs?: { tree: string; objects: string }): NodeJS.ProcessEnv {
52	  const env: NodeJS.ProcessEnv = {};
53	  for (const [key, value] of Object.entries(process.env)) if (!key.startsWith("GIT_")) env[key] = value;
54	  return {
55	    ...env, ...(indexFile ? { GIT_INDEX_FILE: indexFile } : {}), GIT_CONFIG_NOSYSTEM: "1", GIT_ATTR_NOSYSTEM: "1", GIT_NO_REPLACE_OBJECTS: "1",
56	    GIT_ATTR_SOURCE: attrs?.tree ?? EMPTY_TREE, GIT_OPTIONAL_LOCKS: "0", GIT_NO_LAZY_FETCH: "1",
57	    ...(attrs ? { GIT_ALTERNATE_OBJECT_DIRECTORIES: attrs.objects } : {}),
58	  };
59	}
60	
61	/** Drops every `filter` and `diff` assignment (and unset/unspecify forms) from .gitattributes text, macros included. */
62	export function withoutDrivers(text: string): string {
63	  return text.split("\n").map((line) => {
64	    const trimmed = line.trim();
65	    if (!trimmed || trimmed.startsWith("#")) return line;
66	    const head = /^("(?:[^"\\]|\\.)*"|\S+)(\s+|$)/.exec(trimmed);
67	    if (!head) return line;
68	    const rest = trimmed.slice(head[0].length).split(/\s+/).filter(Boolean);
69	    return [head[1], ...rest.filter((token) => !/^[-!]?(filter|diff)(=|$)/.test(token))].join(" ");
70	  }).join("\n");
71	}
72	/**
73	 * The repository states the candidate diff and the debugger snapshot are built for, as one finite predicate over the
74	 * unit's own index and configuration. Inside it the scratch index (base tree, or a copy of the real index) plus the
75	 * worktree is a faithful picture of the candidate: every index entry is a plain stage-0 file or symlink whose
76	 * worktree state git actually checks, and file modes and symlinks are real on the filesystem. Outside it the answer
77	 * would depend on flags that tell git not to look at the worktree (assume-unchanged, skip-worktree, sparse checkout),
78	 * on modes the filesystem cannot report (`core.filemode=false`, `core.symlinks=false`), on case folding, on gitlinks
79	 * (submodules: the diff shows only the pointer), or on an unresolved merge, so it is refused with a reason instead of
80	 * a guess. Also refused: a workspace that is a subdirectory of its repository (attributes and protected-file
81	 * listings would be relative to it), a SHA-256 repository, and a `filter=` attribute in any worktree .gitattributes
82	 * (a clean/smudge filter, such as LFS or git-crypt, makes every filtered file differ from its index blob). Not
83	 * refused, and covered by tests: detached HEAD, linked worktrees, untracked and ignored files, intent-to-add entries,
84	 * renames and copies, symlinks, a merge or cherry-pick in progress once resolved in the index. Known gaps, not
85	 * refused: a `-diff` attribute can make the diff exceed its size limit (reported as too large); `GIT_*` config
86	 * variables are dropped, so the predicate reads the files' configuration only.
87	 * `run` is a pinned git call against the repository's own index (never written); `root` is the workspace.
88	 */
89	const MAX_ATTRIBUTES_BYTES = 1024 * 1024;
90	export type SnapshotSupport = { ok: true } | { unsupported: string };
91	export function snapshotSupport(run: (args: string[]) => string, root: string): SnapshotSupport {
92	  const config = new Map<string, string>();
93	  try {
94	    for (const line of run(["config", "--type=bool", "--get-regexp", "^core\\.(filemode|symlinks|ignorecase|sparsecheckout)$"]).split("\n")) {
95	      const [key, value] = line.split(" ");
96	      if (key) config.set(key.toLowerCase(), value);
97	    }
98	  } catch (err: any) {
99	    if (err?.status !== 1) throw err; // 1 = none of them is set: every default is inside the domain
100	  }
101	  const refuse = (what: string, fix: string): SnapshotSupport => ({ unsupported: `${what}; ${fix}` });
102	  if (run(["rev-parse", "--show-prefix"]).trim()) return refuse("the workspace is a subdirectory of its repository", "run from the repository root");
103	  let format = "sha1";
104	  try { format = run(["rev-parse", "--show-object-format"]).trim(); } catch (err: any) {
105	    // Only a git that does not know the option (it reads it as an unknown revision) is a SHA-1 git; a timeout, a
106	    // permission error or a corrupt repository is not an answer.
107	    if (!/ambiguous argument|unknown option|unknown revision/i.test(String(err?.stderr ?? ""))) throw err;
108	  }
109	  if (format !== "sha1") return refuse(`the repository uses the ${format} object format, which is not supported`, "no workaround");
110	  if (config.get("core.filemode") === "false") return refuse("core.filemode is false, so file modes are not read from disk", "set core.filemode=true");
111	  if (config.get("core.symlinks") === "false") return refuse("core.symlinks is false, so symlinks are checked out as files", "set core.symlinks=true");
112	  if (config.get("core.ignorecase") === "true") return refuse("core.ignorecase is true (a case-insensitive filesystem), so paths cannot be matched exactly", "no workaround");
113	  if (config.get("core.sparsecheckout") === "true") return refuse("a sparse checkout is enabled", "run `git sparse-checkout disable`");
114	  const unmerged = new Set<string>();
115	  for (const entry of run(["ls-files", "-s", "-z"]).split("\0")) {
116	    const m = /^(\d{6}) [0-9a-f]+ (\d)\t([\s\S]*)$/.exec(entry);
117	    if (!m) continue;
118	    if (m[1] === "160000") return refuse(`${m[3].slice(0, 80)} is a submodule (gitlink): only its pointer would be shown, not its content`, "no workaround");
119	    if (m[2] !== "0") unmerged.add(m[3]);
120	  }
121	  if (unmerged.size) return refuse(`${unmerged.size} path(s) have unresolved merge conflicts (for example ${[...unmerged][0].slice(0, 80)})`, "resolve them");
122	  for (const entry of run(["ls-files", "-v", "-z", "--cached"]).split("\0")) {
123	    if (!entry || entry[0] === "H") continue;
124	    const tag = entry[0];
125	    const file = entry.slice(2).slice(0, 80);
126	    if (tag === "S" || tag === "s") return refuse(`${file} is marked skip-worktree (sparse checkout), so git does not look at its worktree state`, "run `git update-index --no-skip-worktree`");
127	    if (tag >= "a" && tag <= "z") return refuse(`${file} is marked assume-unchanged, so git does not look at its worktree state`, "run `git update-index --no-assume-unchanged`");
128	    return refuse(`${file} has index state '${tag}' that is not supported`, "no workaround");
129	  }
130	  // Paths are read as UTF-8 text from here on; a name that is not valid UTF-8 would be mangled into another one.
131	  const everything = run(["ls-files", "-z", "--cached", "--others", "--exclude-standard"]).split("\0");
132	  const mangled = everything.find((p) => p.includes("\uFFFD"));
133	  if (mangled !== undefined) return refuse(`a path (${JSON.stringify(mangled.slice(0, 60))}) is not valid UTF-8 text`, "rename it");
134	  for (const file of everything.filter((p) => p && !p.endsWith("/") && path.posix.basename(p) === ".gitattributes")) {
135	    let text = "";
136	    try {
137	      const full = path.join(root, file);
138	      const st = fs.lstatSync(full);
139	      if (!st.isFile()) continue;
140	      if (st.size > MAX_ATTRIBUTES_BYTES) return refuse(`${file.slice(0, 80)} is larger than ${MAX_ATTRIBUTES_BYTES} bytes, so its attributes cannot be applied`, "shrink it");
141	      text = fs.readFileSync(full, "utf8");
142	    } catch (err: any) {
143	      if (err?.code === "ENOENT") continue; // listed but deleted from the worktree: nothing to apply
144	      return refuse(`${file.slice(0, 80)} could not be read`, "fix its permissions");
145	    }
146	    if (/(^|\s)filter=/m.test(text.split("\n").filter((l) => !l.trim().startsWith("#")).join("\n"))) return refuse(`${file.slice(0, 80)} assigns a clean/smudge filter, so worktree content differs from the index by design`, "no workaround");
147	  }
148	  return { ok: true };
149	}
