151	const DIFF_FLAGS = ["--no-color", "--no-ext-diff", "--no-textconv", "--no-renames", "--relative"];
152	const MAX_DIFF_PATHS = 2_000;
153	const GIT_MAX_BUFFER = 4 * 1024 * 1024;
154	/** Path listings scale with the repository, not the change, so they get room for very large repositories. */
155	const LISTING_MAX_BUFFER = 256 * 1024 * 1024;
156	/** Paths per `check-attr` call, so its output stays small whatever the repository's size. */
157	const ATTR_BATCH = 1_000;
