179	const SOURCE_FILE_MAX = 4 * 1024 * 1024;
180	const SOURCE_TOTAL_MAX = 64 * 1024 * 1024;
181	const ADDED_FILE_MAX = 16 * 1024 * 1024;
182	const SIGNIFICANT_LINE_MIN = 8;
