184	/**
185	 * The content of the protected files present in the workspace (tracked, untracked or ignored), for recognising a new
186	 * file that carries it. A new file is carried when it equals a protected file exactly (whatever its size) or shares a
187	 * significant line with one: a trimmed, non-comment line of at least 8 characters. Files inside `.nexus` take part by
188	 * exact content only (their lines are structural). When the sources cannot all be read within the limits, every new
189	 * file counts as carried: nothing is kept because it could not be compared.
190	 */
191	function protectedContent(sources: Array<{ root: string; file: string }>): { carriedBy(dir: string, relative: string): boolean } {
192	  const hashes = new Set<string>();
193	  const lines = new Set<string>();
194	  let complete = true;
195	  let total = 0;
196	  for (const { root, file } of sources) {
197	    const structural = file.split(/[\\/]/).some((seg) => seg.toLowerCase() === ".nexus");
198	    let size: number;
199	    try {
200	      const st = fs.lstatSync(path.join(root, file));
201	      if (!st.isFile()) continue;
202	      size = st.size;
203	    } catch { continue; }
204	    // A large `.nexus` file (a flight log) is not a credential source: it is left out instead of failing every new file closed.
205	    if (structural && size > SOURCE_FILE_MAX) continue;
206	    if (!structural) total += size;
207	    if (size > SOURCE_FILE_MAX || total > SOURCE_TOTAL_MAX) { complete = false; continue; }
208	    let data: Buffer;
209	    try { data = fs.readFileSync(path.join(root, file)); } catch { complete = false; continue; }
