211	    if (structural) continue;
212	    for (const line of significantLines(data)) lines.add(line);
213	  }
214	  return {
215	    carriedBy(dir: string, relative: string): boolean {
216	      if (!complete) return true;
217	      if (hashes.size === 0 && lines.size === 0) return false;
218	      let data: Buffer;
219	      try {
220	        const st = fs.lstatSync(path.join(dir, relative));
221	        if (!st.isFile()) return false;
222	        if (st.size > ADDED_FILE_MAX) return true;
223	        data = fs.readFileSync(path.join(dir, relative));
224	      } catch { return true; }
225	      if (hashes.has(createHash("sha256").update(data).digest("hex"))) return true;
226	      for (const line of significantLines(data)) if (lines.has(line)) return true;
227	      return false;
228	    },
